# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.54.0/ankra-cli-darwin-arm64"
      sha256 "77b664da039718310dc55a69b2cf52f54dd8ec011e75f2dcfa755dfab89a7352"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.54.0/ankra-cli-darwin-amd64"
      sha256 "eb519e7f49a6dd07b0fb1b85f6e3fe47897fd4fc9b9285e9a2d685edd1929418"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.54.0/ankra-cli-linux-arm64"
      sha256 "52ea066def1fe7404a9cc1bd5aa1aaba6ac1d9734a0d2acf69e2b0dcc7ca06d0"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.54.0/ankra-cli-linux-amd64"
